record = {"id": "JAH-GRID-000339", "name": "Right Triangle 0339", "shape": "right_triangle", "table": [["Leg a", "19.25"], ["Leg b", "5.73"], ["Hypotenuse c", "20.0847"], ["Angle at a", "73.4237\u00b0"], ["Angle at b", "16.5763\u00b0"], ["Area", "55.1513"], ["Perimeter", "45.0647"]]}
prim = {"a": 19.25, "b": 5.73}
def recompute(shape, prim):
    if shape == "right_triangle":
        a, b = prim["a"], prim["b"]
        hyp = math.hypot(a, b)
        return {"Hypotenuse c": hyp, "Area": a * b / 2, "Perimeter": a + b + hyp}
    if shape == "rectangle":
        w, h = prim["w"], prim["h"]
        return {"Diagonal": math.hypot(w, h), "Area": w * h, "Perimeter": 2 * (w + h)}
    if shape == "regular_polygon":
        n, side = prim["n"], prim["side"]
        ap = side / (2 * math.tan(math.pi / n))
        return {"Apothem": ap, "Perimeter": n * side, "Area": n * side * ap / 2}
    if shape == "circle":
        rad = prim["r"]
        return {"Diameter": 2 * rad, "Circumference": 2 * math.pi * rad, "Area": math.pi * rad * rad}
    base, ht = prim["base"], prim["height"]
    eq = math.hypot(base / 2, ht)
    return {"Equal sides": eq, "Area": base * ht / 2, "Perimeter": base + 2 * eq}
stored = {row[0]: float(str(row[1]).replace("\u00b0", "")) for row in record["table"]}
recomputed = recompute(record["shape"], prim)
worst = 0.0
for k, v in recomputed.items():
    worst = max(worst, abs(stored[k] - v))
    assert abs(stored[k] - v) <= 0.001, k
print("program: " + record["id"] + " \u2014 " + record["name"])
print("shape: " + record["shape"])
print("worst recompute difference: " + str(round(worst, 6)))
print("self-check: all asserts passed.")

